import{_ as o,I as a,o as i,c as s,b6 as d,J as r}from"./chunks/framework.BUXTSoD9.js";const m=JSON.parse('{"title":"データ可視化とダッシュボード","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/appendix/5-data/data-visualization.md","filePath":"ja-jp/appendix/5-data/data-visualization.md"}'),n={name:"ja-jp/appendix/5-data/data-visualization.md"};function h(b,t,g,c,p,_){const l=a("ChartTypeSelectorDemo"),e=a("DashboardLayoutDemo");return i(),s("div",null,[t[0]||(t[0]=d('<h1 id="データ可視化とダッシュボード" tabindex="-1">データ可視化とダッシュボード <a class="header-anchor" href="#データ可視化とダッシュボード" aria-label="Permalink to “データ可視化とダッシュボード”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">はじめに</p><p><strong>優れたグラフは千行のデータに勝る。</strong> データ可視化とは、抽象的な数字を直感的な視覚表現に変換し、データの背後にあるストーリーを数秒で理解できるようにする技術です。Excel のグラフから Grafana の監視ダッシュボードまで、可視化は至る所に存在します。</p></div><p><strong>この記事で学べること</strong></p><p>この章を終えると、以下の力が身につきます：</p><ul><li><strong>グラフの選択</strong>：データの目的に応じて最適なグラフタイプを選択できる</li><li><strong>可視化の原則</strong>：データ可視化のコア的なデザイン原則を習得する</li><li><strong>ダッシュボード設計</strong>：異なるタイプのダッシュボードのレイアウトパターンを理解する</li><li><strong>ツールエコシステム</strong>：主要な可視化ツールの位置づけと選定に精通する</li><li><strong>よくある罠</strong>：誤解を招くグラフやよくある可視化の間違いを回避する</li></ul><table tabindex="0"><thead><tr><th>章</th><th>内容</th><th>コア概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>グラフタイプの選択</td><td>比較、トレンド、構成比、分布、関係</td></tr><tr><td><strong>第 2 章</strong></td><td>可視化デザイン原則</td><td>データインク比、一貫性、可読性</td></tr><tr><td><strong>第 3 章</strong></td><td>ダッシュボードレイアウト</td><td>概要型、比較型、ドリルダウン型、リアルタイム型</td></tr><tr><td><strong>第 4 章</strong></td><td>ツール選定</td><td>ECharts、D3、Grafana、Metabase</td></tr><tr><td><strong>第 5 章</strong></td><td>よくある罠</td><td>座標軸の切り詰め、3D 円グラフ、色の乱用</td></tr></tbody></table><hr><h2 id="_0-全景図-なぜ可視化が必要なのか" tabindex="-1">0. 全景図：なぜ可視化が必要なのか？ <a class="header-anchor" href="#_0-全景図-なぜ可視化が必要なのか" aria-label="Permalink to “0. 全景図：なぜ可視化が必要なのか？”">​</a></h2><p>人間の脳は、文字情報を処理するよりも視覚情報を処理する方がはるかに高速です。折れ線グラフがあれば「先月の売上は減少傾向にある」ことがすぐにわかりますが、同じ情報がテーブルで示されている場合は、行ごとに比較してようやく結論に至るでしょう。</p><p>可視化のコア的な価値：</p><ul><li><strong>パターンの発見</strong>：トレンド、周期、外れ値がグラフで一目瞭然</li><li><strong>意思決定の支援</strong>：非技術者でもデータを理解し、意思決定に参加できる</li><li><strong>コミュニケーション効率</strong>：一図は千言に勝ち、データ解釈の曖昧さを減らす</li></ul><div class="tip custom-block"><p class="custom-block-title">可視化 ≠ 美しさ</p><p>可視化の目的は<strong>情報を伝えること</strong>であり、テクニックをひけらかすことではありません。質素でも正確な棒グラフは、派手でも理解しづらい 3D グラフよりもはるかに価値があります。</p></div><hr><h2 id="_1-グラフタイプの選択-正しいグラフで正しいストーリーを" tabindex="-1">1. グラフタイプの選択：正しいグラフで正しいストーリーを <a class="header-anchor" href="#_1-グラフタイプの選択-正しいグラフで正しいストーリーを" aria-label="Permalink to “1. グラフタイプの選択：正しいグラフで正しいストーリーを”">​</a></h2><p>グラフを選ぶ最初のステップは「どのグラフが好きか」ではなく、「何を伝えたいか」です。データの目的が異なれば、最適なグラフタイプも異なります。</p>',15)),r(l),t[1]||(t[1]=d('<h3 id="グラフ選択クイックリファレンス" tabindex="-1">グラフ選択クイックリファレンス <a class="header-anchor" href="#グラフ選択クイックリファレンス" aria-label="Permalink to “グラフ選択クイックリファレンス”">​</a></h3><table tabindex="0"><thead><tr><th>データの目的</th><th>推奨グラフ</th><th>非推奨</th><th>理由</th></tr></thead><tbody><tr><td>大きさの比較</td><td>棒グラフ、横棒グラフ</td><td>円グラフ</td><td>人間の目は角度の違いよりも長さの違いに敏感</td></tr><tr><td>トレンドの表示</td><td>折れ線グラフ、面積グラフ</td><td>棒グラフ</td><td>折れ線の連続性が時間の連続性を暗示する</td></tr><tr><td>構成比の表示</td><td>円グラフ（≤5 分類）、積み上げ棒グラフ</td><td>3D 円グラフ</td><td>3D パースペクティブは面積比を歪める</td></tr><tr><td>分布の表示</td><td>ヒストグラム、箱ひげ図</td><td>折れ線グラフ</td><td>分布は頻度を見る必要があり、トレンドではない</td></tr><tr><td>関係の表示</td><td>散布図、バブルグラフ</td><td>棒グラフ</td><td>2つの連続変数の関係には二次元空間が必要</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">シンプルな判断ルール</p><ul><li><strong>1つの変数</strong> → ヒストグラム（分布）または数値カード（KPI）</li><li><strong>2つの変数</strong> → 折れ線グラフ（時間 vs 数値）または散布図（数値 vs 数値）</li><li><strong>複数カテゴリ</strong> → 棒グラフ（比較）または円グラフ（構成比、≤5 分類）</li><li><strong>多次元</strong> → レーダーチャートまたは平行座標図</li></ul></div><hr><h2 id="_2-可視化デザイン原則-データに語らせる" tabindex="-1">2. 可視化デザイン原則：データに語らせる <a class="header-anchor" href="#_2-可視化デザイン原則-データに語らせる" aria-label="Permalink to “2. 可視化デザイン原則：データに語らせる”">​</a></h2><p>良い可視化とは「見栄えが良い」ことではなく、「分かりやすい」ことです。Edward Tufte が『The Visual Display of Quantitative Information』で提唱したいくつかの古典的な原則は、今でも可視化デザインの重要な参考となっています。</p><table tabindex="0"><thead><tr><th>原則</th><th>説明</th><th>アンチパターン</th></tr></thead><tbody><tr><td>データインク比</td><td>グラフ中でデータ表示に使われる「インク」の割合をできるだけ高くする</td><td>過剰なグリッド線、装飾的要素</td></tr><tr><td>非データ要素の最小化</td><td>情報を伝えない視覚要素を削除する</td><td>3D 効果、ドロップシャドウ、グラデーション背景</td></tr><tr><td>一貫したスケール</td><td>座標軸はゼロから始め、目盛りは均等に。切り詰める場合は明確に注記</td><td>Y 軸が 95 から始まっているのに説明がない</td></tr><tr><td>適切な色の使用</td><td>色で情報をエンコードし、装飾に使わない</td><td>順序付きデータにレインボーカラーを使用</td></tr><tr><td>明確な注記</td><td>タイトル、軸ラベル、凡例、単位はすべて不可欠</td><td>単位がない、時間範囲がない</td></tr></tbody></table><h3 id="_2-1-データインク比-data-ink-ratio" tabindex="-1">2.1 データインク比（Data-Ink Ratio） <a class="header-anchor" href="#_2-1-データインク比-data-ink-ratio" aria-label="Permalink to “2.1 データインク比（Data-Ink Ratio）”">​</a></h3><blockquote><p>グラフ中でデータを表現するための「インク」が、総「インク」に占める割合をできるだけ高くすべきである。</p></blockquote><p>要するに：<strong>情報を伝えない要素はすべて削除する</strong>。</p><table tabindex="0"><thead><tr><th>削除すべきもの</th><th>残すべきもの</th></tr></thead><tbody><tr><td>3D 効果、ドロップシャドウ、グラデーション</td><td>データポイント、軸ラベル</td></tr><tr><td>余分なグリッド線</td><td>重要な基準線（目標値など）</td></tr><tr><td>装飾的アイコン</td><td>凡例（複数系列がある場合）</td></tr><tr><td>派手な背景色</td><td>明確なタイトルと単位</td></tr></tbody></table><h3 id="_2-2-一貫性の原則" tabindex="-1">2.2 一貫性の原則 <a class="header-anchor" href="#_2-2-一貫性の原則" aria-label="Permalink to “2.2 一貫性の原則”">​</a></h3><ul><li><strong>色の一貫性</strong>：同じ次元は異なるグラフでも同じ色を使用。例えば「売上」は常に青</li><li><strong>スケールの一貫性</strong>：座標軸はできるだけ 0 から開始。十分な理由があり、明確に注記する場合を除く</li><li><strong>時間の一貫性</strong>：時間軸の間隔は均等に。不等間隔の時間点を等間隔で描画しない</li></ul><h3 id="_2-3-可読性の原則" tabindex="-1">2.3 可読性の原則 <a class="header-anchor" href="#_2-3-可読性の原則" aria-label="Permalink to “2.3 可読性の原則”">​</a></h3><ul><li><strong>タイトルは結論を述べる</strong>：「月次売上」ではなく「売上は3ヶ月連続で減少」</li><li><strong>重要なポイントに注記</strong>：外れ値や変曲点に注釈を付け、読者の注意を導く</li><li><strong>情報密度をコントロール</strong>：1つのグラフで伝えるコア情報は1〜2個に。詰め込みすぎない</li></ul><div class="tip custom-block"><p class="custom-block-title">色使用の3つのルール</p><ol><li><strong>同じ指標は同じ色</strong>：売上はすべてのグラフで青を使用。ある時は青、ある時は緑にしない</li><li><strong>順序付きデータにはグラデーション</strong>：温度は低→高で青→赤のグラデーション。離散色を使わない</li><li><strong>色覚バリアフリーを考慮</strong>：男性の約 8% が赤緑色覚異常を持つ。重要情報の区別に赤と緑だけを使用しない</li></ol></div><hr><h2 id="_3-ダッシュボードレイアウト-シナリオに応じたパターン選び" tabindex="-1">3. ダッシュボードレイアウト：シナリオに応じたパターン選び <a class="header-anchor" href="#_3-ダッシュボードレイアウト-シナリオに応じたパターン選び" aria-label="Permalink to “3. ダッシュボードレイアウト：シナリオに応じたパターン選び”">​</a></h2><p>ダッシュボード（Dashboard）は複数のグラフの有機的な組み合わせです。良いダッシュボードは、グラフを単に並べるのではなく、使用シナリオに応じた適切なレイアウトパターンを選択します。</p>',19)),r(e),t[2]||(t[2]=d('<h3 id="_4つの一般的なレイアウトパターン" tabindex="-1">4つの一般的なレイアウトパターン <a class="header-anchor" href="#_4つの一般的なレイアウトパターン" aria-label="Permalink to “4つの一般的なレイアウトパターン”">​</a></h3><table tabindex="0"><thead><tr><th>レイアウトパターン</th><th>コア構造</th><th>適用シナリオ</th><th>デザインのポイント</th></tr></thead><tbody><tr><td>全体概要型</td><td>KPI カード + トレンドグラフ + 明細テーブル</td><td>経営陣の日次レポート、運用ダッシュボード</td><td>コア指標を最上部に配置、重要な数字を一目で把握</td></tr><tr><td>比較分析型</td><td>左右対称レイアウト</td><td>A/B テスト、同期比較・環比分析</td><td>比較次元を一貫させ、差異を強調</td></tr><tr><td>ドリルダウン分析型</td><td>集計から明細へ段階的に展開</td><td>売上分析、ユーザー行動分析</td><td>クリックインタラクションをサポート、段階的に深掘り</td></tr><tr><td>リアルタイム監視型</td><td>大きな数字 + リアルタイム曲線 + アラート状態</td><td>大型イベント用スクリーン、サーバー監視</td><td>自動更新、ダーク背景、プロジェクター表示に適している</td></tr></tbody></table><h3 id="ダッシュボード設計の-5-つの原則" tabindex="-1">ダッシュボード設計の 5 つの原則 <a class="header-anchor" href="#ダッシュボード設計の-5-つの原則" aria-label="Permalink to “ダッシュボード設計の 5 つの原則”">​</a></h3><ol><li><strong>まず「誰が見るのか」を問う</strong>：CEO は戦略指標、運用担当者はプロセス指標、エンジニアは技術指標を見る</li><li><strong>5 秒ルール</strong>：ユーザーは 5 秒以内にダッシュボードのコア情報を理解できるべき</li><li><strong>情報の階層</strong>：最も重要なものを左上に、次要なものを下に配置</li><li><strong>スクロールを減らす</strong>：コアコンテンツは1画面に表示。重要データを見るためにスクロールが必要な状態を避ける</li><li><strong>余白を残す</strong>：すべてのスペースを埋めず、適度な余白で視覚的に快適に</li></ol><div class="tip custom-block"><p class="custom-block-title">ダッシュボード vs レポート</p><ul><li><strong>ダッシュボード</strong>：リアルタイム/準リアルタイム、インタラクティブ、監視と迅速な意思決定向け</li><li><strong>レポート</strong>：定期生成（日/週/月）、静的、詳細分析とアーカイブ向け</li></ul><p>両者は代替関係ではなく、補完関係です。ダッシュボードが問題を発見し、レポートが深掘り分析を行います。</p></div><hr><h2 id="_4-ツール選定-コードライブラリから-bi-プラットフォームまで" tabindex="-1">4. ツール選定：コードライブラリから BI プラットフォームまで <a class="header-anchor" href="#_4-ツール選定-コードライブラリから-bi-プラットフォームまで" aria-label="Permalink to “4. ツール選定：コードライブラリから BI プラットフォームまで”">​</a></h2><p>可視化ツールは、コードレベルのグラフライブラリ、データ分析グラフライブラリ、BI プラットフォームの3つのレイヤーに分けられます。どれを選ぶかは、要件の複雑さ、インタラクションの要件、チームの技術力によります。</p><h3 id="_4-1-コードレベルのグラフライブラリ" tabindex="-1">4.1 コードレベルのグラフライブラリ <a class="header-anchor" href="#_4-1-コードレベルのグラフライブラリ" aria-label="Permalink to “4.1 コードレベルのグラフライブラリ”">​</a></h3><table tabindex="0"><thead><tr><th>ツール</th><th>言語/プラットフォーム</th><th>特徴</th><th>適用シナリオ</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>すぐに使える、グラフタイプが豊富、日本語ドキュメントが充実</td><td>業務システムへのグラフ組み込み</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>低レイヤーで柔軟、あらゆる可視化効果をカスタマイズ可能</td><td>高度にカスタマイズされたデータ可視化</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>軽量でシンプル、すぐに使い始められる</td><td>シンプルなグラフニーズ</td></tr><tr><td>Matplotlib</td><td>Python</td><td>科学計算の標準ライブラリ、静的グラフ</td><td>データ分析、論文用グラフ</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>インタラクティブグラフ、3D 対応</td><td>データ探索、Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-bi-プラットフォーム-ノーコード-ローコード" tabindex="-1">4.2 BI プラットフォーム（ノーコード/ローコード） <a class="header-anchor" href="#_4-2-bi-プラットフォーム-ノーコード-ローコード" aria-label="Permalink to “4.2 BI プラットフォーム（ノーコード/ローコード）”">​</a></h3><table tabindex="0"><thead><tr><th>ツール</th><th>位置づけ</th><th>コア的な強み</th><th>適用チーム</th></tr></thead><tbody><tr><td>Grafana</td><td>監視可視化</td><td>時系列データのサポートが良い、アラート統合</td><td>運用/SRE チーム</td></tr><tr><td>Metabase</td><td>軽量 BI</td><td>オープンソースで無料、SQL だけでグラフ作成可能</td><td>中小チームの迅速な構築</td></tr><tr><td>Apache Superset</td><td>エンタープライズ BI</td><td>オープンソース、ビッグデータソース対応</td><td>データチームを持つ企業</td></tr><tr><td>Tableau</td><td>商用 BI</td><td>ドラッグ＆ドロップ操作、可視化効果が良い</td><td>ビジネスアナリスト</td></tr><tr><td>Power BI</td><td>商用 BI</td><td>Microsoft エコシステムとの統合が良い</td><td>Microsoft 技術スタックを使用する企業</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">選定のアドバイス</p><ul><li><strong>開発者が製品にグラフを組み込む</strong> → ECharts（中国語エコシステムが充実）または Chart.js（シンプルなシナリオ）</li><li><strong>データアナリストが探索分析を行う</strong> → Plotly + Jupyter または Metabase</li><li><strong>運用監視ダッシュボード</strong> → Grafana（事実上の標準）</li><li><strong>ビジネスチームのセルフサービス分析</strong> → Metabase（オープンソース）または Tableau（商用）</li><li><strong>高度なカスタマイズが必要</strong> → D3.js（学習曲線は急だが、最も柔軟性が高い）</li></ul></div><hr><h2 id="_5-よくある罠-これらのグラフはあなたを騙している" tabindex="-1">5. よくある罠：これらのグラフはあなたを騙している <a class="header-anchor" href="#_5-よくある罠-これらのグラフはあなたを騙している" aria-label="Permalink to “5. よくある罠：これらのグラフはあなたを騙している”">​</a></h2><p>データ可視化は諸刃の剣です。使い方が良ければ真実を明らかにし、悪ければ錯覚を生み出します。以下は最も一般的な可視化の罠であり、すべてのデータ従事者が識別できるべきものです。</p><h3 id="_5-1-座標軸の切り詰め" tabindex="-1">5.1 座標軸の切り詰め <a class="header-anchor" href="#_5-1-座標軸の切り詰め" aria-label="Permalink to “5.1 座標軸の切り詰め”">​</a></h3><p>Y 軸の開始点を 0 から大きな数字に変更すると、わずかな違いが巨大な変化のように見えます。</p><table tabindex="0"><thead><tr><th>シナリオ</th><th>実際の差</th><th>視覚的な印象</th></tr></thead><tbody><tr><td>Y 軸が 0 から開始</td><td>製品 A 98 点、製品 B 95 点</td><td>差は小さい</td></tr><tr><td>Y 軸が 90 から開始</td><td>同じデータ</td><td>A は B の数倍に見える</td></tr></tbody></table><p><strong>いつ切り詰めてよいか？</strong> データの絶対値が大きく変化が小さい場合（例：株価が 100 から 105 ほど）は、切り詰めが合理的ですが、必ず明確に注記する必要があります。</p><h3 id="_5-2-3d-円グラフのパースペクティブの罠" tabindex="-1">5.2 3D 円グラフのパースペクティブの罠 <a class="header-anchor" href="#_5-2-3d-円グラフのパースペクティブの罠" aria-label="Permalink to “5.2 3D 円グラフのパースペクティブの罠”">​</a></h3><p>3D パースペクティブは、観察者に近いセクターをより大きく見せます。25% のセクターが 3D 視点では 35% に見えることがあります。</p><p><strong>解決策</strong>：3D 円グラフは絶対に使用しない。通常の円グラフやドーナツグラフを使用するか、思い切って棒グラフを使う。</p><h3 id="_5-3-色の乱用" tabindex="-1">5.3 色の乱用 <a class="header-anchor" href="#_5-3-色の乱用" aria-label="Permalink to “5.3 色の乱用”">​</a></h3><table tabindex="0"><thead><tr><th>誤ったアプローチ</th><th>正しいアプローチ</th></tr></thead><tbody><tr><td>赤と緑でデータを表現する</td><td>青とオレンジなど色覚安全な配色を使用する</td></tr><tr><td>各カテゴリに異なる色を使用する</td><td>同じ系列は同色系の濃淡で表現する</td></tr><tr><td>連続データに色をエンコードするが凡例を付けない</td><td>常に色の凡例と数値注記を提供する</td></tr><tr><td>背景色とデータ色のコントラストが不十分</td><td>WCAG AA レベルのコントラストを確保する</td></tr></tbody></table><h3 id="_5-4-その他のよくある間違い" tabindex="-1">5.4 その他のよくある間違い <a class="header-anchor" href="#_5-4-その他のよくある間違い" aria-label="Permalink to “5.4 その他のよくある間違い”">​</a></h3><table tabindex="0"><thead><tr><th>罠</th><th>問題</th><th>修正</th></tr></thead><tbody><tr><td>双軸（デュアル Y 軸）</td><td>関連のない2つの指標が X 軸を共有し、因果関係を暗示する</td><td>2つのグラフに分けるか、因果関係がないことを明記</td></tr><tr><td>面積の誤解</td><td>円の面積ではなく半径で数値を表現する</td><td>数値が2倍になると面積が2倍になり、半径が2倍になるわけではない</td></tr><tr><td>不均一な時間軸</td><td>1月、3月、12月の間隔が同じ</td><td>実際の時間割合に従って配置</td></tr><tr><td>カテゴリが多すぎる</td><td>円グラフに15のセクターがある</td><td>5つを超えるカテゴリには棒グラフを使用するか、「その他」に統合</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">可視化の倫理規範</p><p>可視化の目的は<strong>理解を助けること</strong>であり、<strong>認知を操作すること</strong>ではありません。グラフを作成するたびに自問してください：</p><ul><li>私が読者だとしたら、このグラフは誤った結論を導くだろうか？</li><li>不利なデータを隠していないか？</li><li>座標軸、スケール、色はデータを公正に表現しているか？</li></ul></div><hr><h2 id="まとめ" tabindex="-1">まとめ <a class="header-anchor" href="#まとめ" aria-label="Permalink to “まとめ”">​</a></h2><p>データ可視化は、データの価値を伝える「ラストマイル」です。どれほど優れた分析でも、正しく理解されなければ、分析しなかったのと同じです。</p><p>本章の重要なポイントを振り返りましょう：</p><ol><li><strong>正しいグラフを選ぶ</strong>：データの目的（比較、トレンド、構成比、分布、関係）に応じてグラフタイプを選択</li><li><strong>デザイン原則</strong>：高いデータインク比、一貫性、可読性が3つのコア原則</li><li><strong>ダッシュボードレイアウト</strong>：概要型、比較型、ドリルダウン型、リアルタイム型の4つのパターンが大部分のシナリオをカバー</li><li><strong>ツール選定</strong>：ECharts から Grafana まで、チームの能力と要件の複雑さに応じて選択</li><li><strong>罠を避ける</strong>：座標軸の切り詰め、3D 円グラフ、色の乱用が最も一般的な誤導手段</li></ol><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Edward Tufte の可視化の古典</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts 公式ドキュメント</a> - 最も人気のある中国語グラフライブラリ</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - 強力な低レイヤー可視化ライブラリ</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - 監視可視化の事実上の標準</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - グラフタイプ選択のデシジョンツリー</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - 色覚バリアフリーの配色スキームツール</li></ul>',35))])}const u=o(n,[["render",h]]);export{m as __pageData,u as default};
